/* Chess-Publisher v1.06.00-beta.47 — English manual access. */
(function(){'use strict';
const BETA='1.06.00-beta.47';
const MANUAL_B64='';
function decodeManual(){try{const bin=atob(MANUAL_B64);const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);return new TextDecoder('utf-8').decode(bytes);}catch(err){console.error('Embedded manual decode failed:',err);return '<!doctype html><html><body><h1>Chess-Publisher User Manual</h1><p>The embedded manual could not be decoded.</p></body></html>';}}
function ensureManualModal(){let m=document.getElementById('cpUserManualModal');if(m)return m;m=document.createElement('div');m.id='cpUserManualModal';m.className='modal-overlay';m.style.display='none';m.innerHTML='<div class="modal-window" style="width:min(1120px,96vw);height:92vh;max-width:96vw;display:flex;flex-direction:column"><div class="modal-titlebar" style="display:flex;align-items:center;justify-content:space-between;gap:10px"><span>Chess-Publisher User Manual</span><button id="cpUserManualCloseTop" type="button">×</button></div><div class="modal-body" style="padding:0;flex:1;min-height:0"><iframe id="cpUserManualFrame" title="Chess-Publisher User Manual" style="width:100%;height:100%;border:0;background:#fff"></iframe></div><div class="modal-bottom"><button id="cpUserManualClose" type="button">Close</button></div></div>';document.body.appendChild(m);const close=()=>{m.style.display='none';};m.querySelector('#cpUserManualClose')?.addEventListener('click',close);m.querySelector('#cpUserManualCloseTop')?.addEventListener('click',close);m.addEventListener('click',e=>{if(e.target===m)close();});return m;}
function openManual(){try{const m=ensureManualModal(),f=m.querySelector('#cpUserManualFrame');if(f&&!f.dataset.loaded){f.srcdoc=decodeManual();f.dataset.loaded='1';}m.style.display='flex';return true;}catch(err){console.error('Manual open failed:',err);try{window.appAlert?.('The embedded user manual could not be opened.','User Manual','warning');}catch(_e){}return false;}}
function install(){document.documentElement.dataset.chesspublisherVersion=BETA;document.title=`Chess-Publisher v${BETA}`;const title=document.getElementById('windowDocumentTitle');if(title)title.textContent=`Chess-Publisher v${BETA} — Tournament Manager & Publisher`;const controls=document.querySelector('.desktop-status-controls')||document.querySelector('.titlebar .window-controls')||document.querySelector('.window-controls');if(controls&&!document.getElementById('cpUserManualBtn')){const b=document.createElement('button');b.id='cpUserManualBtn';b.type='button';b.className='titlebar-save';b.textContent='Manual';b.title='Open English User Manual (F1)';b.onclick=e=>{e.stopPropagation();openManual();};const save=document.getElementById('manualSaveButton');controls.insertBefore(b,save||controls.firstChild);}if(!window.__cpManualF1Installed){window.__cpManualF1Installed=true;document.addEventListener('keydown',e=>{if(e.key==='F1'){e.preventDefault();openManual();}});}}
window.cpOpenUserManual=openManual;window.cpBeta47={version:BETA,openManual};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();
